import{_ as o,a0 as i,w as d,s as r,ao as t,I as l,x as e,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"浅述内核中“挂起到空闲”的实现 | LCTT x X-CMD","titleTemplate":false,"description":"浅述内核中“挂起到空闲”的实现 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"浅述内核中“挂起到空闲”的实现 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"浅述内核中“挂起到空闲”的实现 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20161018 Suspend to Idle","title":"浅述内核中“挂起到空闲”的实现","tag":"201703","desc":""},"relativePath":"201703/20161018 Suspend to Idle.md","filePath":"[post].md"}'),c={name:"201703/20161018 Suspend to Idle.md"};function u(m,s,h,g,f,b){const a=i("Link");return d(),r("div",null,[s[18]||(s[18]=t('<h1 id="浅述内核中-挂起到空闲-的实现" tabindex="-1">浅述内核中“挂起到空闲”的实现 <a class="header-anchor" href="#浅述内核中-挂起到空闲-的实现" aria-label="Permalink to “浅述内核中“挂起到空闲”的实现”">​</a></h1><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h3><p>Linux 内核提供了多种睡眠状态，各个状态通过设置系统中的不同部件进入低耗电模式来节约能源。目前总共有四种睡眠状态，分别是：挂起到空闲（suspend to idle）、加电待机（power-on standby（standby））、挂起到内存（suspend to ram）和挂起到磁盘（suspend to disk）。这些状态分别对应 ACPI 的 4 种状态：S0，S1，S3 和 S4。挂起到空闲（suspend to idle）是纯软件实现的，用于将 CPU 维持在尽可能深的 idle 状态。加电待机（power-on standby（standby））则使设备处于低功耗状态，并且关闭所有非引导 CPU。挂起到内存（suspend to ram）就更进一步，关闭所有 CPU 并且设置 RAM 进入自刷新模式。挂起到磁盘（suspend to disk）则是最省功耗的模式，关闭尽可能多的系统，包括关闭内存。然后内存中的内容会被写到硬盘，待唤醒计算机的时候将硬盘中的内容重新恢复到内存中。</p><p>这篇博文主要介绍挂起到空闲（suspend to idle）的实现。如上所说，它主要通过软件实现。一般平台的挂起过程包括冻结用户空间并将外围设备调至低耗电模式。但是，系统并不是直接关闭和热插拔掉 CPU，而是静静地强制将 CPU 进入空闲（idle）状态。随着外围设备进入了低耗电模式，除了唤醒相关的中断外不应有其他中断产生。唤醒中断包括那些设置用于唤醒系统的计时器（比如 RTC，普通计时器等）、或者电源开关、USB 和其它外围设备等。</p><p>在冻结过程中，当系统进入空闲状态时会调用一个特殊的 cpu 空闲函数。这个 <code>enter_freeze()</code> 函数可以和调用使 cpu 空闲的 <code>enter()</code> 函数一样简单，也可以复杂得多。该函数复杂的程度由将 SoC 置为低耗电模式的条件和方法决定。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><h4 id="platform-suspend-ops" tabindex="-1"><code>platform_suspend_ops</code> <a class="header-anchor" href="#platform-suspend-ops" aria-label="Permalink to “platform_suspend_ops”">​</a></h4><p>一般情况，为了支持 S2I，系统必须实现 <code>platform_suspend_ops</code> 并提供最低限度的挂起支持。这意味着至少要完成 <code>platform_suspend_ops</code> 中的 <code>valid()</code> 函数。如果挂起到空闲（suspend to idle）和挂起到内存（suspend to ram）都要支持，valid 函数中应使用 <code>suspend_valid_only_mem</code>。</p>',8)),l("p",null,[s[1]||(s[1]=e("不过，最近内核增加了对 S2I 的自动支持。Sudeep Holla 提出了一个变更，可以让系统不需要满足 ",-1)),s[2]||(s[2]=l("code",null,"platform_suspend_ops",-1)),s[3]||(s[3]=e(" 条件也能提供 S2I 支持。这个补丁已经被接收并将合并在 4.9 版本中，该补丁可从这里获取： ",-1)),n(a,{href:"https://lkml.org/lkml/2016/8/19/474"},{default:p(()=>[...s[0]||(s[0]=[e("https://lkml.org/lkml/2016/8/19/474",-1)])]),_:1}),s[4]||(s[4]=e("。",-1))]),s[19]||(s[19]=t(`<p>如果定义了 <code>suspend_ops</code>，那么可以通过查看 <code>/sys/power/state</code> 文件得知系统具体支持哪些挂起状态。如下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /sys/power/state</span></span>
<span class="line"><span>freeze mem</span></span></code></pre></div><p>这个示例的结果显示该平台支持 S0（挂起到空闲（suspend to idle））和 S3（挂起到内存（suspend to ram））。按 Sudeep 的变更，那些没有实现 <code>platform_suspend_ops</code> 的平台将只显示 freeze 状态。</p><h4 id="唤醒中断" tabindex="-1">唤醒中断 <a class="header-anchor" href="#唤醒中断" aria-label="Permalink to “唤醒中断”">​</a></h4><p>一旦系统处于某种睡眠状态，系统必须要接收某个唤醒事件才能恢复系统。这些唤醒事件一般由系统的设备产生。因此一定要确保这些设备驱动使用唤醒中断，并且将自身配置为接收唤醒中断后产生唤醒事件。如果没有正确识别唤醒设备，系统收到中断后会继续保持睡眠状态而不会恢复。</p><p>一旦设备正确实现了唤醒接口的调用，就可用来生成唤醒事件。请确保 DT 文件正确配置了唤醒源。下面是一个配置唤醒源示例，该文件来自（<code>arch/arm/boot/dst/am335x-evm.dts</code>）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>     gpio_keys: volume_keys@0 {</span></span>
<span class="line"><span>               compatible = “gpio-keys”;</span></span>
<span class="line"><span>               #address-cells = &lt;1&gt;;</span></span>
<span class="line"><span>               #size-cells = &lt;0&gt;;</span></span>
<span class="line"><span>               autorepeat;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>               switch@9 {</span></span>
<span class="line"><span>                       label = “volume-up”;</span></span>
<span class="line"><span>                       linux,code = &lt;115&gt;;</span></span>
<span class="line"><span>                       gpios = &lt;&amp;gpio0 2 GPIO_ACTIVE_LOW&gt;;</span></span>
<span class="line"><span>                       wakeup-source;</span></span>
<span class="line"><span>               };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>               switch@10 {</span></span>
<span class="line"><span>                       label = “volume-down”;</span></span>
<span class="line"><span>                       linux,code = &lt;114&gt;;</span></span>
<span class="line"><span>                       gpios = &lt;&amp;gpio0 3 GPIO_ACTIVE_LOW&gt;;</span></span>
<span class="line"><span>                       wakeup-source;</span></span>
<span class="line"><span>               };</span></span>
<span class="line"><span>       };</span></span></code></pre></div><p>如上所示，有两个 gpio 键被配置为唤醒源，在系统挂起期间，其中任何一个键被按下都会产生一个唤醒事件。</p><p>可替代 DT 文件配置的另一个唤醒源配置就是设备驱动，如果设备驱动自身在代码里面配置了唤醒支持，那么就会使用该默认唤醒配置。</p><h3 id="实施" tabindex="-1">实施 <a class="header-anchor" href="#实施" aria-label="Permalink to “实施”">​</a></h3><h4 id="冻结功能" tabindex="-1">冻结功能 <a class="header-anchor" href="#冻结功能" aria-label="Permalink to “冻结功能”">​</a></h4><p>如果系统希望能够充分使用挂起到空闲（suspend to idle），那么应该在 CPU 空闲驱动代码中定义 <code>enter_freeze()</code> 函数。<code>enter_freeze()</code> 与 <code>enter()</code> 的函数原型略有不同。因此，不能将 <code>enter()</code> 同时指定给 <code>enter</code> 和 <code>enter_freeze</code>。至少，系统会直接调用 <code>enter()</code>。如果没有定义 <code>enter_freeze()</code>，系统会挂起，但是不会触发那些只有当 <code>enter_freeze()</code> 定义了才会触发的函数，比如 <code>tick_freeze()</code> 和 <code>stop_critical_timing()</code> 都不会发生。这会导致计时器中断唤醒系统，但不会导致系统恢复，因为系统处理完中断后会继续挂起。</p><p>在挂起过程中，中断越少越好（最好一个也没有）。</p><p>下图显示了能耗和时间的对比。图中的两个尖刺分别是挂起和恢复。挂起前后的能耗尖刺是系统退出空闲态进行记录操作，进程调度，计时器处理等。因延迟的缘故，系统进入更深层次空闲状态需要花费一段时间。</p><p><img src="http://www.linaro.org/wp-content/uploads/2016/10/blog-picture-one-1024x767.png" alt="blog-picture-one"></p><p><em>能耗使用时序图</em></p><p>下图为 ftrace 抓取的 4 核 CPU 在系统挂起和恢复操作之前、之中和之后的活动。可以看到，在挂起期间，没有请求或者中断被处理。</p><p><img src="http://www.linaro.org/wp-content/uploads/2016/10/blog-picture-2-1024x577.png" alt="blog-picture-2"></p><p><em>Ftrace 抓取的挂起/恢复活动图</em></p><h4 id="空闲状态" tabindex="-1">空闲状态 <a class="header-anchor" href="#空闲状态" aria-label="Permalink to “空闲状态”">​</a></h4><p>你必须确定哪个空闲状态支持冻结。在冻结期间，电源相关代码会决定用哪个空闲状态来实现冻结。这个过程是通过在每个空闲状态中查找谁定义了 <code>enter_freeze()</code> 来决定的。CPU 空闲驱动代码或者 SoC 挂起相关代码必须确定哪种空闲状态实现冻结操作，并通过给每个 CPU 的可应用空闲状态指定冻结功能来进行配置。</p><p>例如， Qualcomm 会在平台挂起代码的挂起初始化函数处定义 <code>enter_freeze</code> 函数。这个工作是在 CPU 空闲驱动已经初始化后进行，以便所有结构已经定义就位。</p><h4 id="挂起-恢复相关驱动支持" tabindex="-1">挂起/恢复相关驱动支持 <a class="header-anchor" href="#挂起-恢复相关驱动支持" aria-label="Permalink to “挂起/恢复相关驱动支持”">​</a></h4><p>你可能会在第一次成功挂起操作后碰到驱动相关的 bug。很多驱动开发者没有精力完全测试挂起和恢复相关的代码。你甚至可能会发现挂起操作并没有多少工作可做，因为 <code>pm_runtime</code> 已经做了你要做的挂起相关的一切工作。由于用户空间已经被冻结，设备此时已经处于休眠状态并且 <code>pm_runtime</code> 已经被禁止。</p><h3 id="测试相关" tabindex="-1">测试相关 <a class="header-anchor" href="#测试相关" aria-label="Permalink to “测试相关”">​</a></h3><p>测试挂起到空闲（suspend to idle）可以手动进行，也可以使用脚本/进程等实现自动挂起、自动睡眠，或者使用像 Android 中的 <code>wakelock</code> 来让系统挂起。如果手动测试，下面的操作会将系统冻结。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ # echo freeze &gt; /sys/power/state</span></span>
<span class="line"><span>[  142.580832] PM: Syncing filesystems … done.</span></span>
<span class="line"><span>[  142.583977] Freezing user space processes … (elapsed 0.001 seconds) done.</span></span>
<span class="line"><span>[  142.591164] Double checking all user space processes after OOM killer disable… (elapsed 0.000 seconds)</span></span>
<span class="line"><span>[  142.600444] Freezing remaining freezable tasks … (elapsed 0.001 seconds) done.</span></span>
<span class="line"><span>[  142.608073] Suspending console(s) (use no_console_suspend to debug)</span></span>
<span class="line"><span>[  142.708787] mmc1: Reset 0x1 never completed.</span></span>
<span class="line"><span>[  142.710608] msm_otg 78d9000.phy: USB in low power mode</span></span>
<span class="line"><span>[  142.711379] PM: suspend of devices complete after 102.883 msecs</span></span>
<span class="line"><span>[  142.712162] PM: late suspend of devices complete after 0.773 msecs</span></span>
<span class="line"><span>[  142.712607] PM: noirq suspend of devices complete after 0.438 msecs</span></span>
<span class="line"><span>&lt; system suspended &gt;</span></span>
<span class="line"><span>….</span></span>
<span class="line"><span>&lt; wake irq triggered &gt;</span></span>
<span class="line"><span>[  147.700522] PM: noirq resume of devices complete after 0.216 msecs</span></span>
<span class="line"><span>[  147.701004] PM: early resume of devices complete after 0.353 msecs</span></span>
<span class="line"><span>[  147.701636] msm_otg 78d9000.phy: USB exited from low power mode</span></span>
<span class="line"><span>[  147.704492] PM: resume of devices complete after 3.479 msecs</span></span>
<span class="line"><span>[  147.835599] Restarting tasks … done.</span></span>
<span class="line"><span>/ #</span></span></code></pre></div><p>在上面的例子中，需要注意 MMC 驱动的操作占了 102.883ms 中的 100ms。有些设备驱动在挂起的时候有很多工作要做，比如将数据刷出到硬盘，或者其他耗时的操作等。</p><p>如果系统定义了冻结（freeze），那么系统将尝试挂起操作，如果没有冻结功能，那么你会看到下面的提示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ # echo freeze &gt; /sys/power/state</span></span>
<span class="line"><span>sh: write error: Invalid argument</span></span>
<span class="line"><span>/ #</span></span></code></pre></div><h3 id="未来的发展" tabindex="-1">未来的发展 <a class="header-anchor" href="#未来的发展" aria-label="Permalink to “未来的发展”">​</a></h3><p>目前在 ARM 平台上的挂起到空闲（suspend to idle）有两方面的工作需要做。第一方面工作在前面 <code>platform_suspend_ops</code> 小节中提到过，是总允许接受冻结状态以及合并到 4.9 版本内核中的工作。另一方面工作是冻结功能的支持。</p><p>如果你希望设备有更好的响应及表现，那么应该继续完善冻结功能的实现。然而，由于很多 SoC 会使用 ARM 的 CPU 空闲驱动，这使得 ARM 的 CPU 空闲驱动完善它自己的通用冻结功能的工作更有意义了。而事实上，ARM 正在尝试添加此通用支持。如果 SoC 供应商希望实现他们自己的 CPU 空闲驱动或者需要在进入更深层次的冻结休眠状态时提供额外的支持，那么只有实现自己的冻结功能。</p><hr>`,34)),l("p",null,[s[6]||(s[6]=e("via: ",-1)),n(a,{href:"http://www.linaro.org/blog/suspend-to-idle/"},{default:p(()=>[...s[5]||(s[5]=[e("http://www.linaro.org/blog/suspend-to-idle/",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=e("作者：",-1)),n(a,{href:"http://www.linaro.org/author/andygross/"},{default:p(()=>[...s[7]||(s[7]=[e("Andy Gross",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),n(a,{href:"https://github.com/beyondworld"},{default:p(()=>[...s[8]||(s[8]=[e("beyondworld",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),n(a,{href:"https://github.com/jasminepeng"},{default:p(()=>[...s[9]||(s[9]=[e("jasminepeng",-1)])]),_:1})]),l("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const P=o(c,[["render",u]]);export{C as __pageData,P as default};
